async function advanceEngagement(id,action){const row=engagementRows().find(x=>x.id===id);if(!row)return;const next=action==='conflict'?engagement.STATUS.CONFLICT_PENDING:engagement.STATUS.ENGAGEMENT_CONFIRMED;if(action==='confirm'&&!confirm('Confirm that conflict review is complete and the attorney has accepted the engagement under separate engagement terms? Case documents will still remain private until the provider grants access.'))return;try{engagement.assertTransition(row.status,next,'attorney');if(fb()&&!row.localProvider)await window.AuditDefendFirebaseAPI.advanceProviderEngagement(id,next);row.status=next;row.attorneyUid=uid()||'local-attorney';row.updatedAt=new Date().toISOString();if(row.localProvider){const p=localProviderPayload();p.invite={...p.invite,...row};localStorage.setItem(PROVIDER_KEY,JSON.stringify(p))}else{const index=state.engagements.findIndex(x=>x.id===id);state.engagements[index]={...state.engagements[index],...row}}save();render();toast(next+'. Documents remain private until the provider grants access.')}catch(e){toast(e.message||String(e))}}
