  claims.forEach(claim=>{const source=sourceRecords[claim.id],docs=docsFor(claim.id),requiresDocs=claim.issues?.includes('Documentation support'),status=claim.rebuttal==='A'?'accepted':!requiresDocs?'other':source?.status==='verified'||docs.some(item=>item.type!=='submission-proof')?'evidence-ready':(shared.provider.unavailable||[]).includes(claim.id)?'unavailable':'evidence-missing';counts[status]++});
  const filters=[['all','All claims'],['accepted','Accepted by payer'],['evidence-ready','Documentation evidence ready'],['enrollment','All enrollment findings'],['enrollment-doc','Enrollment + documentation'],['enrollment-only','Enrollment only'],['evidence-missing','Documentation still missing'],['unavailable','Cannot supply']],updates=(shared.comparison.activity||[]).filter(item=>item.actor==='Provider'),notifications=(shared.comparison.notifications||[]).filter(item=>item.audience==='attorney');
